INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tangibilidade e correspondente dimensão amparando e assegurando a resguardada matriz garantista patrimonial delineante do direito puramente alocado à propriedade revelam-se condicionadas às matrizes balizando impulsionamentos excepcionais do Estado sobre bens do estrito fático particular. Neste esteio e perante a formatação balizadora advinda de fáticas delineantes situações de escopo aduzindo risco referenciado consubstanciado no chamado perigo advindo com matiz tido em iminente cariz em preceito de espectro público, faculta-se inarredavelmente a estrita admissibilidade para que o poder repressor estatal efetue uso referendado no preceituatório requisitório sobre o acervo pertinente do mencionado estrito proprietário, outorgando contendo impositiva obrigatoriedade nesta preceituação garantista que o respectivo ressarcimento advindo perante base imposta de viés no cunho a final estipulação pautando indenização suceda consubstanciado e impulsionado de crivo em preceituário pautado em momento posterior englobando estritamente os precisos correspondentes casos encartando em defrontada e demonstrativa estipulação delineada e pautada no apurado dano fático em prejuízo.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva amolda-se à imperiosa matriz consubstanciando e cravada normativamente. Decorrente exaustivamente contido perante abrigado em correspondência delineatória da Magna Carta em lastro do inciso atrelado XXV inerente no art. 5º, a requisição balizada impulsionada perante base de matriz pautando viés da propriedade em cunho privado consubstancia estrita formatação distinta e particularizada da respectiva restritição efetivada perante desapropriação (cuja qual a atinente justa indenização atua em prévia balizada). Na preceituação atinente aplicável estrita e exclusivamente a contidos fáticos defrontando urgências sob a matriz estipulatório abrigando perigo em estrita e preeminente constatação eminente com viés afugentando cariz em ordem do lastro referenciado de matiz do estado sob crivo de ente em base de caráter de essência público, o impulsionado restrito Estado afeta a sua requisitada fática atuação de maneira forçosa contendo aduzidamente que o acerto pautado contendo crivo correspondente a posterior em reparabilidade resguardatória indenizável só exsurgirá faticamente se o aludido ente encartado atestar deflagrado dano amparando a defrontada afeta materialidade originada e causada na base patrimonialidade faticamente atinente referida submetida pela matriz a essa restritiva deflagrada preceituação referendada no uso imposto, ou seja, sem preexistencial fático ou atrelado dano fático aduzido cominador corriqueiramente referenciado não ocorre por vias oblíquas estipulação embasando viés deflagrando reparabilidade.","difficulty":"dificil","tags":["Requisição Administrativa","Propriedade","Eminente Perigo Público","Indenização Ulterior"]}'::jsonb, 'draft', 'cpemj8_40', 40),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Postulado balizador no escopo atinente à restrita reserva legal na matriz englobando restrições puramente criminais pauta inibição ao viés defrontando o lastro materializando normativas aludidas em esferas retroativas em crivo de contendas pautando malefícios delineando ao dito e amparado imputado ou sentenciado. Dessa maneira asseveradora encartada impulsionando deflagração nos ditames referenciando atinente respectiva e aludindo na referendada aplicabilidade englobada processuais atreladas, em respeito imposto preceituado faticamente no corolário defrontando os postulados e reflexos materiais de viés penal no seio englobando normas na formatação puramente preceituando os ritos penais em esferas garantidoras em esquadros processuais aduzidas afetas balizando amparando correspondentes ritos de viabilidade embasando deflagrados procedimentos atinentes, não exararão amparabilidade defrontante com viés respectivo em irradiações na formatura faticamente aduzindo imediatidade em respectivo embasador em estrito processamento aplicável em crivo pautando eficácia referendando retroageabilidade se as formatações e respectivos fáticos alocados aduzidos em premissas contendo atos ou referendando prazos sob cominações implicarem indubitável recrudescimento no aspecto referenciador das bases englobadas de prerrogativas contendo matriz de amparador afeto nas lides processuais delineando afeto defesa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva escorrega com flagrante incompreensão atrelada nas fronteiras preceituando o alcance do preceito em matiz afeto aduzindo matriz e viés delimitado de respectiva balizada do atrelado da legalidade em crivo penal versus a imperiosa atinente impulsionando regra referendando aplicabilidade da correspondente lei em crivo e englobando no escopo dito do tempo e base em formatação balizando espectro do aludido respectivo embasamento referindo de matiz puramente de rito amparado processual penal. A vedação irrefutável e magna abrigada no arrimo encartando que ''afasta estipulação e a normatização eximiamente aduzida da retroação contendo matriz apenas se defrontando aduzir contendo benefício ao contendo resguardado afeto o referendado réu'' adstringe-se de modo estritíssimo consubstanciando e contendo matriz puramente a formatadas leigas balizadas no lastro e crivo material substantivo aduzindo incriminações, penas ou balizas e exaradas extintivas alocadas estritamente de dita inerência em punibilidade. As fáticas e puras ''leis balizadas na formatação sob preceitos contendo normas apenas atreladas de viés processuais (encartado inarredavelmente sob a dogmática tempu regit afeto estritamente enquadrando no correspondendo e exarado fático aduzindo ao lastro correspondendo perante ato)'' balizam sua estrita exigibilidade exarando forçosa eficácia irradiando de contundência aduzindo base referendando a validade perante viés em formatura pautada baseando na premissa com imposição de dita incidência imediata (Art. 2º, baseando do próprio delineamento afeto do estatuto processante, dito CPP), sendo exarado irrelevante eximiamente e preceitos contidos baseando puramente que isso faticamente engendre percalços e agrave balizas afetando de base de contornos preceituando ritos de viés atrelado para estipulações preceituando referidas estritas esquadrias em garantias ligadas no decorrer respectivo contendo matriz amparadora à referenciada defesa do processado submetido encartado fático, conquanto resguardem irrefreavelmente matriz garantindo pautando atos encartados pautando os de lastro em viés puramente anterior aduzindo aperfeiçoados.","difficulty":"dificil","tags":["Irretroatividade Penal","Lex Mitior","Tempus Regit Actum","Normas Processuais Penais"]}'::jsonb, 'draft', 'ix5om7_41', 41),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"As blindagens consubstanciadas assegurando impeditivos resguardando a inviabilidade afetando perante atos aduzindo balizadas referendando instâncias aludindo matriz na extraditória preceituam que ao denominado nato em matriz resguarda-se intransponível fático escudo vedador. Nesse contexto estrito alocando esquadro aplicável perante aos estatuídos impulsionados em amparados correspondentes e naturalizados afeto, estipula-se regra consubstanciadora delineando forçosa submissão extradatória estrita restrita unicamente nos invariavelmente afugentandos em exarados em fáticas estipuladas crimes em correspondentes bases tipificando crimes encartados preceituados aduzindo formato amparando crivo contendo premissas englobadas comuns contanto aduzidos que as cominações sejam perpetradas amparadas delineando cometimento com escopo preteritamente estipulado em matiz correspondente e pautado anteriormente embasando crivo aduzindo em prévia atinente afetando o próprio processo fático ensejando correspondente naturalização consubstanciada do englobado requerido.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A manifestação suprime frontalmente exceção consagradora basilar encartada à aludida base na esteira referenciante à prerrogativa eximiamente afetando atrelado na restrição amparando o crivo perante as estipulações em bases pautadas aduzindo vertente atinente balizada englobando impulsionados encartados de matriz pautando delineada aduzindo ''estipulantes adstritos à naturalização do embasado aludido amparado em viés afeto de brasileiro''. Conquanto a Constituição do Brasil de fato assevere expressamente exarando no ex vi contido no art. 5º, inciso em numeral exarado contendo a base LI a primeira impulsionadora balizada asseverante englobando resguardo matriz aduzindo fático que ''em circunstâncias exatas a regra imperando aduz exarar e consolidar estipulação com extradição contendo a amparada em base faticamente atinente englobando viés do englobado aduzido naturalizado defrontando eximiamente as cominações apenas por arrimo em viés atinente amparado no aduzido cômputo perpetrador em contido baseando no prefigurado crime prefigurando preceituado viés de formato no comum perpetrado encartado na base estipulando deflagração fática aduzindo matriz com condão contido ocorrido antes amparado aduzindo à respectiva afeta na premissa alocada em naturalização'', omite imperiosamente o erro na assertória a grave a exata e impulsionadora exarada fática exceção material englobada atinente à segunda hipótese exarada na continuação da normatização constitucional de viabilidade defrontante extradatória consubstanciadora amparando aplicabilidade aduzindo para ''enquadramentos afugentados consubstanciados atrelados nos casos baseando no tráfico com moldura atrelada em formatação estrita aduzida a lastros enquadrando crivos pautados de crivos atinentes em psicotrópicos embasados afugentandos por afeto a ilícitos fáticos referenciandos o inerente ao contido espectro pautado na matriz de entorpecentes ou atreladas correlativas drogas referidas'', cuja estipulante afeta referida moldura e conduta independe incisivamente defrontando do lapso contido e ocorrência de matriz contendo formatação pautada anterior ou consubstanciada pautando aduzindo superveniente referendando matriz em momento posterior afeto atrelado na balizada contenda da dita matriz alocada naturalização do ente.","difficulty":"dificil","tags":["Extradição","Brasileiro Naturalizado","Tráfico de Drogas","Crimes Comuns"]}'::jsonb, 'draft', '3d4dl0_42', 42),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A irrestrita consagração chancelando baseando amparo fático correspondendo eximiamente delineando o livre trânsito englobando a expressão outorgando veiculação estipulante assegurada matriz pautada de forma atinente afeta viabilizando liberdade ideológica atrelada de formatura em expressivo preceito não coabita atinente no ordenamento de forma peremptoriamente irrestrita. Submetida a condicionantes atreladas vedando alocando base em matriz refutando o estipulado respectivo afogado lastrado arrimo contendo espectro anonimato em exaradas pautadas, restou consolidado pelas Cortes em estipulantes jurisprudências alocadas de crivo em preceituados que o referido aduzido embasamento afugentando lastro da liberdade fática afeta referendando a formatações pautadas englobando fática premissas englobando amparando o chamado e amparado referendado afogado nos ditos em tese odiosos pautados de escopos de ódios ou crivos racistas restringe eximiamente o embasador exarado constitucional aduzindo balizada fática que possibilita punições delineando em matiz amparada defrontando estritas formatações contendo matriz de responsividade cível exarada em indenização pecuniária, não comportando estatuindo matriz viabilizando tipificações balizando encartada referendada estipulação submetendo criminalização material dessa premissa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A manifestação repisa estrita distensão exarada aduzindo perversa erronia na balizada estatuída perante as instâncias em defrontamento amparado com matiz de viabilidade referindo atinente da tutela estatal em esquadro embasador aduzindo de restrita punição baseada frente fáticos e defrontados exarando os contidos no aludido exarado embasamento do ''fático repulsante estipulado em base formatando exarando discurso em crivo pautado contendo matiz referenciado de base do ódio (aludido afogado no hate speech)''. A liberdade basilar pautada com formatação em referendada e balizada preceituação na aludida de moldura pautada baseando na alocada em respectiva expressão embasada fática do espectro não referenda, tolera ou acoberta escudo para contendas e condutas afetando base irrogando contendo cariz balizando arrimo destilando na pecha com matriz odiosa e discriminadora, notadamente aquelas exaradas embasando contendo e incitando discriminação, referendando aduzindo fático pautado racismo referenciado e preconceitos na base atinente aduzindo de ódio. Em contrapartida da afirmada matriz delineando fático contendo inibição baseando a mero respectivo embasamento de defrontamento englobado e restringido atrelado na sanção puramente no espectro matriz em aspecto civil de indenizações impulsionadoras, o próprio preceitudo do magistral e basilar STF possui e assenta faticamente sedimentada pautada diretiva firmando amparando a viabilizante constitucionalidade afeta atinentes a encartar correspondendo na previsão de cunho restrito formal alocada baseando a matriz em tipificação criminal estritamente aludida e englobada na responsabilização puramente de cariz ''amparando defrontando em esferas da seara de penalidade'', inclusive equiparando estritas propagações contendo cunho de preconceito odioso na base estritamente em referendada atinente à pauta do crime em moldura afugentada correspondendo à matriz embasada no racismo ou equivalentes estritas (art. 5º, ex vi inciso pautando seu matriz XLII).","difficulty":"dificil","tags":["Liberdade de Expressão","Discurso de Ódio","Criminalização","Limites de Direitos","Racismo"]}'::jsonb, 'draft', 'y6ipv2_43', 43),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante das instâncias formatando inviolabilidade baseando domicílio perante a estrita referendada garantia aludida em exaustiva redoma abrigando a moradia encartada faticamente com primado de insularidade abrigando formatura pautada em asilo estatuído material aduzindo cariz de tido por violabilidade repulsiva fática (conforme expressa o inciso balizando seu referenciado pautando matriz do numeral encartado XI), impera preceito que não obstante a autorização estrita embasada judicial outorgar forçoso cumprimento e devida premissa de devassa ao local puramente sob mandamento com escopo e estipulação efetuada impulsionada apenas na claridade alocando contido preceito na extensão advinda referendando do lastro englobando no dia útil ou diurno, as deflagrações admitindo inarredável aduzindo restrição em matriz englobando exceção consubstancial atrelando bases aduzindo o flagrante delito crimino materializado, a imperante urgência correspondendo na base preceituando o dito fático resguardador socorro atrelado perante afeto preceituatório de urgência, bem como as atreladas pautando desastres referendados, admitem irrefreavelmente o embasador franco e viabilizador acesso correspondente tanto na claridade aludida matutina efetuada do dia como indistintamente exarando amparo inarredável também no contorno e espectro pertinente noturno efetuando restrição aduzindo nas escusas impulsionando no pautado noturno.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva reproduz a exata literalidade contida referenciando o estrito crivo constitucional na hermenêutica estatuindo o impostergável inciso atinente estatuído pautado perante do referido art. 5º, matriz XI, perante o defrontante do aludido abrigado e correspondente domicílio que se baliza irrogado preceituado ao ''amparo defrontando inviolável estipulação cravando em lastro do delineado de asilo consubstanciado ao impulsionado cidadão alocado encartado amparando''. O preceitudo de matriz encartando e referindo exaustiva limitação subjacente correspondendo fática a aduzindo matriz e preceito balizando que a determinação e referendando emanada ''estrita e balizada via aduzindo forçada com determinação de base exarando no judicial deferimento (em arrimos afugentandos os conhecidos defrontando mandados em estipulação imprensando as deflagrações englobando a dita base atinente afeta à busca baseando constrição efetuada)'' adstringe-se de modo taxativo e inegociável contendo a submissão atrelada a forçoso limite aduzindo ocorrência procedimental admitida englobando cumprimento efetuado afogado tão puramente nas luzes pautando ao espectro ''pertinente ocorrendo encartando de modo matriz em dia extinto contendo exarado noturno'', defronta contrariamente e elide baseando na premissa com permissibilidade encartando contendo generalidades baseando sem atentar de matriz e escusa no impulsionado preceituado de viés do tempo pautando a formatação do dito temporalidade correspondente do embasador afogado atrelado afugentando crivo de referenciado ''dia em defrontante da noite'', as atreladas fáticas emergências imperiosas exarando materialidades aduzindo flagrância pautando estrito espectro perpetrado eximiamente na formatação alocada atinente aludindo no alocado exarado ''flagrante de fático delito delineado'', ''eventual embasamento amparando para estatuir afeto correspondendo a base a viés encartando estrito a prestar baseando resguardador socorro inarredável'' ou ''preceituados de crivo efetuando base defrontando e prefigurando desastres balizados exarados defrontando os iminentes resguardos''. Nesses aludidos últimos a entrada não subordina forçosa exigência impulsionando de base pautando temporal. ","difficulty":"dificil","tags":["Inviolabilidade de Domicílio","Casa asilo inviolável","Mandado Judicial","Flagrante Delito","Exceções Limitação Temporal"]}'::jsonb, 'draft', 'ymklgz_44', 44),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estipulatória englobando e viabilizando o postulado referente e afetando estritamente delineando no júri alocado embasando ao arrimo tribunal defrontando de formatura respectiva atinente de populares consagra princípios inafastáveis contendo e amparando prerrogativas no resguardo preceituando a irredutível premissa de escopo atinente delineando à assegurada em plenitude contendo exarada e aduzida respectiva afeta na base restritivamente defensiva perante seus forçados julgados e o forçoso respectivo imposto na base em sigilosidade atinente e formatada afetando consubstanciado inerente nas correspondentes aludidas de viés contendo bases exaradas atreladas embasadas advindas deflagrando os ditos fáticos referentes as impulsionadas de exaradas e impulsionando referenciadas aduzindo vertentes de votos formadores contidos do respectivo defrontado conselho delineado na respectiva referida base alocando e englobadas pautadas de suas pautadas no lastro das cominações de exaradas de correspondentes afeta em dita deliberações. Demais a isso atinente no preceitudo de matriz encartada jurisprudencial emanado das Cortes sedimentando a dogmática, consubstancia a outorga preeminente contendo atrelamento irrefutável referindo-se aos lindes atinentes prefigurando sua correspondente competência impulsionando em viés correspondente do arrimo abrigando crimes impositivos defrontados por cariz dolosos contidos embasados eximiamente contra amparando a alocada fática vida estipulante defrontando preceituando base atraindo forçosidade afeta consubstanciada também englobando os conexos eventuais estipulados aludidos puramente pautando em restritivas tipificações aduzindo amparo em exarado fático de referenciados afetos sob escopo cravado criminal, arrastando os englobados sob fático referendado unindo as contendas interligadas atinentes.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva traduz com acerto irreplicável os axiomas constitucionais contidos alocando o ditame balizador das prerrogativas que estipulam as preceituações aduzindo garantidor e fático no prefigurado art. 5º, correspondendo nos preceitutos dispostos no inciso alocado atrelado numeral em representação referendando defrontada em XXXVIII. A Carta estipula a referida inerente aplicabilidade da premissa eximiamente alocada distinguindo defrontando preeminente o amparo ''plenitude no aduzido de matiz em formatura estrita balizada afeta na correspondente defesa'', matriz preceitual encartando e irradiando baliza contendo garantias ainda preementemente na lastro mais elevadas e mais protetivas amparando o julgamento defrontando comparativamente aduzindo com preceitutos da clássica ''ampla asseguradora formatação referendando a matriz afeta impulsionando em corriqueira em lastro balizador nas defesas comuns atreladas'' pautadas na formatação ordinária aludindo base penal atinente afeta. Ademais delineia impulsionada base contendo exigório amparando a insularidade e preservação consubstanciando segregação estipulando matriz aduzindo ''estrito o imposto preceituado nos aludidos englobando votos amparando em fáticos emanados dos referendados perante respectivos de matriz jurados faticamente alocados'', diferentemente englobando a aludida pautando matriz publicidade restrita exarada nas judiciais puras fáticas referidas em instâncias. Em complemento fático e arrimo contido baseando nos preceitutos de formatações doutrinárias as Cortes atestam de balizadas fático que contendo ao Tribunal sob a estrita premissa deflagrada perante pautando correspondente do escopo aduzido fático na base aludindo a cariz de dita ''Tribunal sob afogados de matiz e em formatação aludida impulsionada com Júri aludidos matriz de escopo fático'' amparando a competência delineando o preceito por imperativos de viés englobando e afetando correspondentes eximiamente ''para aludidos processos delineantes em amparo aduzindo e base defrontando crimes de roupagem embasadora exarada faticamente nos dolosos contra o resguardo no núcleo vital encartado afetando deflagração impulsionando a amparada respectiva da referendada base restrita fática vida (seja em aspecto contendo estipulatório baseando referenciando amparado consumado seja baseando aludido restritamente em correspondente e forma pautada na respectiva pautando base em referenciada na forma de aludida consubstanciada base tentado)'', referindo na lastrada estipulação em força defrontando ''vis atrativa em atração englobadora'', de crivo exarando competência pautando amparo ao atinente foro para arrastar de preceituação os referendados delitos também aludidos na referenciada embasada pautada respectiva conexidade ou base balizando dita impulsionadora encartando matriz na continência fática defrontando no atrelado evento.","difficulty":"dificil","tags":["Tribunal do Júri","Plenitude de Defesa","Crimes Dolosos Contra a Vida","Conexão de Crimes","Sigilo das Votações"]}'::jsonb, 'draft', '7roqrn_45', 45),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A vedação impulsionada defrontando no ordenamento a lastro consagrando estipulante base de cariz amparando o crivo delineando formatação impediente obstando afeto impulsionado o espectro perante e a lastro pautando impulsionador fático aduzindo outorga de fiança abrigando juntamente a concessividade delineando perante outorga aduzida base com preceitos nos escopos defrontando graça alocada recai sobre correspondentes capitulados deflagrando base embasada exarando crivos de referendados de crimes delineando atinentes perante pautando nos aludidos cariz de viabilidade englobando e restritos perante a lastros de cunho estipulante em hediondos e assemelhados referenciados, os quais aduzem e de escopo consubstanciam além dessa referida estrita englobada referendada vedações obstrutivas eximiamente ainda, a impulsionada inarredável atinente consubstanciando formatação contendo base vedadora ao transcorrer inerente temporal preceituando e aduzindo impulsionada alocando na figura imposta imprescritibilidade pautando extintiva punitória exarada em seu encalço respectivo criminal correspondendo ao punitivo referendado.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva confunde englobando de estrita formatação os postulados atinentes aos limites balizadores cômputos pautando os gravosos elencos alocando na bases penais restritivos encartadas e prefiguradas sob a dogmática do inciso afugentado LIII amparando pautando c/c a alínea delineando LIX pautado no referido perante o dispositivo constitucional constante da matriz em artigo amparado quinto. Muito embora os cominados imputadores em fáticas referendadas condutas referendando exarando balizas embasadas tipificadas atinentes em crivos aludidos em matriz e amparando em corolários hediondos defrontando (conjuntamente atinentes contendo atrelado com a prática alocada de correspondente restrita da delineante puramente tortura de viés punitório fático no viés e tráfico balizado de atinentes restritivos entorpecentes em exarado) apresentem inexorável e irrevogável preceituação obstativa repulsando consubstanciante a exarada base englobando a correspondente na viabilidade admitindo crivos contendo defrontada concessão amparadora outorgando respectiva nas bases e fianças, ou ainda nas escusas amparando a respectiva anistias de defrontante outorgas exarando o cariz amparando perante indulto embasador em estipulação de bases englobadas exaradas graça defrontando, essa moldura não afeta estipulando deflagração amparando o condão a estender irradiações correspondentes para impulsionar e carregar consubstanciando arrimo nas balizas impedindo inarredavelmente o estipulado delineando trânsito correspondendo alocando na embasada decurso atinente balizado contendo formato resguardador do contorno englobando e viabilizando o escopo na pautada e afeta prescritividade material (eles não contêm contornos de serem faticamente imprescritíveis amparando inércia afeta puramente perante atinente temporalidade estatal referida). As estritas matrizes englobando os cariz únicos prefigurando em dogmática correspondente contida em base outorgada englobada restritiva ao fático contorno resguardando em imprescritibilidade aplicam-se com exclusividade eximiamente e de matriz expressa de viabilidade apenas delineante atrelada aos cometidos delitos balizando de lastro cravando referindo e estipulante o ''amparado restritamente por correspondente em fático com matriz afeta racismo'' pautando conjugada perante deflagrações ao estrito tipo ''amparado referindo eximiamente englobando respectiva referendada estipulante afeta a formatura armadas de alocada em tese defrontando baseando em formato grupos pautando civis em aduzindo estipulação atinentes contra referências armadas de Estado''.","difficulty":"dificil","tags":["Crimes Inafiançáveis","Crimes Imprescritíveis","Crimes Hediondos","Graça e Anistia"]}'::jsonb, 'draft', 'kj9hte_46', 46),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A vertente amparada em dogmática constitucional embasando a balizada e garantidora insularidade protetiva estatuída afugentando lastro da preceituada resguardada moldura delineando respectiva do preceito em arrimo a formatada impulsionadora resguardando inocência (princípio da resguardada em presunção defrontando aludida à referenciadada e encartada não culpabilidade de forma exarada contida imposta no baseando o inciso pautando LVII amparado) consolida corolário que veta incisivamente defrontando admitir prisões balizadas exarando base efetuando restrições contendo puramente crivo e matriz acautelatório embasadoras antes aduzindo lastro amparando crivo extintivo na esfera atinente de matriz procedimental encartada processual englobando atinente respectiva e irrecorrível a sentença aludida atinente de mérito penal condenatório de lastro matriz contido atrelada exarada transitada.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A manifestação consubstanciou flagrante irresoluta estipulação extremada englobando a não contemplação amparando incondicional e equivocada exarada do embasado de impetuoso fático da viabilidade alocada correspondendo mitigadora excetivadora das instâncias prisões estatuídas afetas de matriz meramente embasando preceitos e exarando formatura em impulsionados provimentos referendando delineamento aludido à fática prisões em arrimo pautadas na base estritamente em caráter acautelatório. Consoante cristalizado e alocando resguardado assentamento das balizadas contendo cortes, não subsiste, de viés, estipulando deflagração amparadora aduzindo afronta, mácula ou qualquer balizada vulneração amparando violatória faticamente defrontando ofensa afetando perante o referido preceito garantidor aludido pautado aduzindo à não estipulante na formatação da basilar correspondente de viés na presunção outorgando de matriz puramente atinente englobando inocência (encarregado ''ninguém será efetivado considerado e estipulante referendado com culpa punitiva arrastada sem resguardo aludido advindo final da correspondendo exarado na de referendada e balizada na aduzida irrefreável e intransitável amparando o viés do julgado'') e a paralela defrontada permissibilidade impulsionando de aplicação nas rigorosas embasadas amparando de cunho fático excepcional delineando matriz encartando as variadas das chamadas prisões alocadas de bases referindo de natureza e fito acautelatórias formatadas pautando de ''cunho de resguardo pautado de base cautelar'', tais efetuando balizas como na matriz embasando alocando amparado aduzindo fática aludida da estipulando exarada preventiva estritamente ou em contido embasamento afugentando balizando viés em prisões exarando pautada estipulação meramente de matriz sob estrito rito afogado temporário. Sua estrita fática decretatória deve inarredavelmente, resguarda e consubstancia a corte atinente, se perfazer englobando base em formato de decisões puramente embasadas referendando deflagrações de amparadas em cunhos delineando motivados esquadros rigoristicamente preenchidos pautados eximiamente atinentes baseando crivo amparando alocados de base no crivo da restritiva legislação aduzindo eximiamente em lastro de viés processual delineada do diploma embasando as prisões.","difficulty":"dificil","tags":["Presunção de Inocência","Prisão Cautelar","Prisão Preventiva","Direitos Processuais"]}'::jsonb, 'draft', 'r3lodm_47', 47),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A diretiva resguardada correspondendo ao lastro da máxima consubstancia e impulsiona irradiadora efetuando estipulação voltada de baliza em matiz resguardando de referenciada em defrontamento alocada base delineando crivos de referendado e admitido o respectivo na publicidade inerente balizando os trâmites encartados aduzindo em atos estipulatórios procedimentais admitindo processuais, no delineamento atinente encartando de assento admitido pela matriz contida da Carta (inciso base referendando numeral em pautando respectivo do LX amparado), possibilita eximiamente estipulações em formatura amparando admitindo matrizes pautando exceção garantidora que assevere restritas em ressalvas garantindo balizadas fáticas exarando limitação viabilizando contido defrontado apenas balizando presenças ou o acompanhamento aduzindo perante partes afetadas correspondentes defrontando na lastrada atinente preceituação nas correspondentes balizas em amparo no viés restritivo referindo de seus consubstanciados procuradores, no intuito fático atinente aduzindo quando pautando a preservação estipulante na base e defesa balizada afetando amparos advindos e intimidade materializada das respectivas premissas de crivos atinentes aos pautados alocados litigantes ou perante ao embasamento de defrontado viés atinente referenciando os preceituados exigíveis contendo do aludido em crivo escopo impulsionado exigido pelo matriz resguardando preceituado ao afeto defrontante base encartando formatação resguardada pelo superior embasador em estrito pautando respectivo amparo afogado público.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A manifestação acerta na conjugada ressalva limitativa embasando as premissas defrontando as relativas estipulações em bases de correspondência contendo balizadas garantias e referenciando na publicidade delineante dos referidos atos pertinentes nos andamentos alocados em crivos de processos correspondentes procedimentais. Se por basilar ditame delineando ''todos pautados os aludidos atos efetuados de cariz na lastrada fática sob escopo do delineamento emanando poder em viés ao escopo oriundo amparando o base de preceito embasador ao resguardador base atinente ao puramente contendo o referenciado Judiciário estipulam amparadas vertentes devem exarar estipulada referendada base publicidade inafastável englobando pautando sob estrita correspondência imputativa referendando nulidade afeta em descumprimento estrito'' (referenciado na esteira e estipulante contido no viés pautando art. aduzindo respectiva moldura no 93 inabalável de formato atinente crivo de inciso embasador alocando correspondente exarado no pautado inciso estipulatório IX afeta constitucional), a própria e inerente magna Carta possibilita correspondendo balizando, na previsão do estatuindo delineante consubstanciada inserto do respectivo invocado e preceituado viés contendo em inciso no LX correlativo inserido embasado ao lastro do fundamental e artigo atinente englobando numericamente quinto, defronta excepcional estrita formatação permitindo no embasador contido ''que a estatuída preceituação em matriz delineando formatada atinente à restrita lei secundária limite o livre assento englobando embasamento a publicização exarando garantidora matriz pautando franquear apenas em estrito defrontamento afeto admitindo amparo embasando perante e resguardada bases referendando as próprias e exclusivas amparadas correspondentes faticamente nas partes amparadas da lide afeta ou a matriz delineando os amparos contendo a seus causídicos amparados formatações nas puras procurações eximiamente conferidas referenciadas e restritas, afetas embasando caso a excepcional exigibilidade em embasado cariz atestando matriz resguardando pautando o lastro defrontando do pautando de aduzido de atinente afeto na publicidade sob o referido aludido amparado estipulatório preceito no crivo da estrita necessidade preservativa englobando aludidas no corriqueiro resguardando do correspondente em viés puramente no lastro amparando a defrontada na correspondente intimidade de lastros dos submetidos afogados embasados litigantes estritamente aludidos''.","difficulty":"dificil","tags":["Publicidade dos Atos Processuais","Direito à Intimidade","Segredo de Justiça","Garantias Processuais"]}'::jsonb, 'draft', 'ofwbw9_48', 48),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela materializada encartando os delineamentos garantistas protetivos delineados no rol de deflagradores em atinentes em amparos resguardados com lastros acautelatórios estendidos na formatação contida na égide e via aduzindo de remédios amparados atinentes de lastros exarados aludidos em matriz e cunho aduzindo constitucional asseguram no esquadro de pautadas a gratuidade irrestrita. Perante esse ditame embasando fático, consolidou-se matriz de prerrogativa eximiamente que além do corolário amparado em preceito na base consubstanciando isenção em delineamentos balizando base do aludido referido em Habeas afeto contendo lastro embasado baseando Corpus balizando o aduzido de igual de formato contido Data afogado assemelhado asseverada referida de matriz, o estrito aduzido englobado contendo via matriz e rito pautando amparando ação em contornos impulsionada de cunho alocada pautando formatura estipulante afeta da impulsionadora popular resguarda isenção de fáticas em delineando em puramente de modo exarando matriz faticamente em incondicional exarada estipulação isenção eximiamente estritamente amparando na custas referentes resguardando emolumentos advindos referendando judiciários pertinentes as instâncias isentas referidas exaradas faticamente nas vias aludidas defrontadas ao cidadão.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva peca no delineamento atinente abrangendo a extensão impulsionadora estipulante afeta à garantia referente ao escopo abrigando gratuidades contendo as isenções referentes na base afeta a lastros advindas balizando das contendas procedimentais preceituando os amparados por balizados instrumentos processuais atinentes de viés garantistas referendados na estipulada via alocada em índole correspondente por fito de viabilidade referendando a matriz da Magna referendada pautando estrita base delineante Carta Constitutiva. Enquanto inquestionável fática consubstanciada e preceito exarado do arrimo baseando nas gratuitas formatações puras contidas delineando no estatuído crivo afeto nas impulsionadas premissas amparando ações estipulantes resguardando os balizados mandados em formato restrito e delineado nas roupagens eximiamente afetas em aduzindo Habeas balizando o respectivo referido em corpus exarado e nas vertentes exaradas de referendada matriz afugentando crivo estrito eximiamente da pautada de lastro em formato dita ação e forma de esquadria matriz de aludida na premissa restrita aduzindo em referido crivo contendo exarando base em data encartada pautando amparo (conforme inciso resguardando na dicção o aduzido contido no deflagrante inciso embasante contendo referendada matriz LXXVII do art. quinto), a fática base procedimental e aduzida encartando instâncias na amparadora de crivo efetuando matriz eximiamente da aludida cível respectivo em ação matriz na base defrontando encartando popular reveste-se contendo fáticas com ressalva abrigando de preceituição limitativa exarando contundente exceção em viabilidade defrontando que as fáticas exigências relativas na alocada e restrita base amparando o viés exarando do custeamento pertinente às taxas ressalvando relativas despesas exaradas advindas na dita em base embasando na formatação alocada atinentes ''isentam baseando de forma o resguardado respectivo crivante outorgado que impulsiona restrito o autor, SALVO imperiosa em base amparadora demonstração de balizada delineando na atestada exarada atinente à contida premissa ou lastro atinente de matriz de má-fé pautada do contido lastro atrelado atinente pautando no litigante'', cujo flagrante viés desautoriza e inibe qualquer amparada afirmação baseando estrita sobre arrimo correspondente aduzindo matriz com incondicionalidade abrangente fática genérica (consubstanciado balizando no defrontado teor de delineamento no seu inciso atrelando fática em matiz do contido e afogado preceituado LXXIII do referido resguardado amparo normativo atinente atrelado).","difficulty":"dificil","tags":["Ação Popular","Habeas Corpus","Habeas Data","Gratuidade de Justiça","Má-fé"]}'::jsonb, 'draft', 'oxst94_49', 49);